// Normaliza campos ignorando BOM (\uFEFF) no nome das chaves
function getField(obj, ...names) {
  const clean = Object.fromEntries(
    Object.entries(obj).map(([k, v]) => [k.replace(/^\uFEFF/, '').toLowerCase(), v])
  );
  for (const name of names) {
    const val = clean[name.toLowerCase()];
    if (val !== undefined && val !== null && val !== '') return val;
  }
  return '';
}

return $input.all()
  .map(item => {
    const r = item.json;
    // suporte a formato flat (campos no raiz) e formato nativo Airtable ({fields:{...}})
    const src = r.fields || r;
    return {
      json: {
        recordId: r.id || r.recordId,
        title:    getField(src, 'Title', 'title', 'name') || 'Sem título',
        googleId: getField(src, 'Google ID', 'googleId', 'google_id', 'googleID'),
        link:     getField(src, 'Link', 'link', 'url'),
        quality:  getField(src, 'Quality', 'quality') || 'Pending'
      }
    };
  })
  .filter(item => item.json.recordId && (item.json.googleId || item.json.link));
